const body = $json.body ?? {};
const headers = $json.headers ?? {};

const tieneCampo = (campo) =>
  Object.prototype.hasOwnProperty.call(body, campo);

const textoOpcional = (campo) => {
  if (!tieneCampo(campo)) return null;
  return String(body[campo] ?? '').trim();
};

// --------------------
// Sesión
// --------------------

let session_token = body.session_token
  ? String(body.session_token).trim()
  : null;

const authorization =
  headers.authorization ??
  headers.Authorization ??
  '';

if (!session_token && typeof authorization === 'string') {
  const match = authorization.match(/^Bearer\s+(.+)$/i);

  if (match) {
    session_token = match[1].trim();
  }
}

// --------------------
// Acción
// --------------------

const actionRaw = String(body.action ?? '')
  .trim()
  .toUpperCase();

let action = actionRaw;

if (actionRaw === 'CREAR') {
  action = 'CREATE';
}

if (['LISTADO', 'READ', 'CONSULTAR'].includes(actionRaw)) {
  action = 'LIST';
}

if (actionRaw === 'ACTUALIZAR') {
  action = 'UPDATE';
}

if (actionRaw === 'CANCELAR') {
  action = 'CANCEL';
}

// --------------------
// Datos
// --------------------

const evento_id = body.evento_id
  ? String(body.evento_id).trim()
  : null;

const inscripcion_id = body.inscripcion_id
  ? String(body.inscripcion_id).trim()
  : null;

const nombre_acreditacion =
  textoOpcional('nombre_acreditacion');

const observaciones =
  textoOpcional('observaciones');

const origen = String(body.origen ?? 'WEB')
  .trim()
  .toUpperCase();

// --------------------
// Validación
// --------------------

const accionesPermitidas = [
  'CREATE',
  'LIST',
  'UPDATE',
  'CANCEL'
];

let error = null;

if (!accionesPermitidas.includes(action)) {
  error = 'Acción no válida';
}

if (!error && !session_token) {
  error = 'El token de sesión es obligatorio';
}

if (!error && action === 'CREATE' && !evento_id) {
  error = 'evento_id es obligatorio';
}

if (
  !error &&
  ['UPDATE', 'CANCEL'].includes(action) &&
  !inscripcion_id
) {
  error = 'inscripcion_id es obligatorio';
}

if (!error && action === 'UPDATE') {
  const hayCambios =
    nombre_acreditacion !== null ||
    observaciones !== null;

  if (!hayCambios) {
    error =
      'Debe enviarse al menos un dato permitido para actualizar';
  }
}

return [{
  json: {
    route: error ? 'INVALID' : action,
    action,
    session_token,
    evento_id,
    inscripcion_id,
    nombre_acreditacion,
    observaciones,
    origen,
    error
  }
}];

