const entrada =
  $('Normalizar y validar inscripción').first().json;

const sesion =
  $('Buscar sesión CREATE').first().json;

const evento =
  $('Buscar evento CREATE').first().json;

const inscripciones =
  $('Leer inscripciones CREATE')
    .all()
    .map(item => item.json)
    .filter(item => item.inscripcion_id);

const usuarioId =
  String(sesion.usuario_id ?? '').trim();

const eventoId =
  String(evento.evento_id ?? '').trim();

// -------------------------
// 1. Buscar duplicado activo
// -------------------------

const estadosActivos = new Set([
  'CONFIRMADA',
  'LISTA_ESPERA'
]);

const duplicada = inscripciones.find(inscripcion => {
  const mismoUsuario =
    String(inscripcion.usuario_id ?? '').trim() === usuarioId;

  const mismoEvento =
    String(inscripcion.evento_id ?? '').trim() === eventoId;

  const estado =
    String(inscripcion.estado ?? '')
      .trim()
      .toUpperCase();

  return (
    mismoUsuario &&
    mismoEvento &&
    estadosActivos.has(estado)
  );
});

// -------------------------
// 2. Contar confirmadas
// -------------------------

const confirmadas = inscripciones.filter(inscripcion => {
  return (
    String(inscripcion.evento_id ?? '').trim() === eventoId &&
    String(inscripcion.estado ?? '')
      .trim()
      .toUpperCase() === 'CONFIRMADA'
  );
}).length;

const capacidad =
  Number(evento.capacidad ?? 0);

const cuposDisponibles =
  Math.max(capacidad - confirmadas, 0);

// -------------------------
// 3. Calcular lista de espera
// -------------------------

const esperaEvento = inscripciones.filter(inscripcion => {
  return (
    String(inscripcion.evento_id ?? '').trim() === eventoId &&
    String(inscripcion.estado ?? '')
      .trim()
      .toUpperCase() === 'LISTA_ESPERA'
  );
});

const ordenes = esperaEvento
  .map(inscripcion =>
    Number(inscripcion.orden_espera ?? 0)
  )
  .filter(numero =>
    Number.isFinite(numero) && numero > 0
  );

const siguienteOrden =
  ordenes.length > 0
    ? Math.max(...ordenes) + 1
    : 1;

// -------------------------
// 4. Estado que correspondería
// -------------------------

const estadoNuevo =
  cuposDisponibles > 0
    ? 'CONFIRMADA'
    : 'LISTA_ESPERA';

const ordenEspera =
  estadoNuevo === 'LISTA_ESPERA'
    ? siguienteOrden
    : null;

return [{
  json: {
    usuario_id: usuarioId,
    evento_id: eventoId,

    duplicada_activa: !!duplicada,

    inscripcion_existente_id:
      duplicada?.inscripcion_id ?? null,

    estado_existente:
      duplicada?.estado ?? null,

    capacidad,
    inscripciones_confirmadas: confirmadas,
    cupos_disponibles: cuposDisponibles,

    estado_nuevo: estadoNuevo,
    orden_espera: ordenEspera,

    nombre_acreditacion:
      entrada.nombre_acreditacion,

    observaciones:
      entrada.observaciones,

    origen:
      entrada.origen
  }
}];

