        .trim()
        .toUpperCase(),

    orden_espera:
      analisis.estado_nuevo === 'LISTA_ESPERA'
        ? analisis.orden_espera
        : ''
  }
}];

const crypto = require('crypto');

const inscripcion =
  $('Preparar inscripción CREATE').first().json;

return [{
  json: {
    auditoria_id: `audins_${crypto.randomUUID()}`,
    inscripcion_id: inscripcion.inscripcion_id,
