const usuarioId =
  $('Buscar sesión LIST').first().json.usuario_id;

const inscripciones =
  $('Leer inscripciones LIST')
    .all()
    .map(item => item.json)
    .filter(item => item.inscripcion_id)
    .sort((a, b) => {
      return new Date(b.fecha_inscripcion ?? 0).getTime()
        - new Date(a.fecha_inscripcion ?? 0).getTime();
    })
    .map(item => ({
      inscripcion_id: item.inscripcion_id,
      usuario_id: item.usuario_id,
      evento_id: item.evento_id,
      estado: item.estado,
      fecha_inscripcion: item.fecha_inscripcion,
      fecha_actualizacion: item.fecha_actualizacion,
      nombre_acreditacion: item.nombre_acreditacion,
      observaciones: item.observaciones,
      origen: item.origen,
      orden_espera:
        item.orden_espera === ''
          ? null
          : item.orden_espera
    }));

return [{
  json: {
    ok: true,
    tipo: 'LIST',
    usuario_id: usuarioId,
    resultado_count: inscripciones.length,
    inscripciones
  }
}];

